INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 1, 'theory', 'Квиз: зачем виртуализация и условия Попека — Голдберга');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 0, 'Что из перечисленного НЕ является выгодой виртуализации?', '["Изоляция: сбой одной машины не ломает соседей","Снимки и перенос работающих машин между серверами","Ускорение каждой отдельной программы по сравнению с запуском на голом железе","Более плотная загрузка сервера несколькими машинами"]', 2, 'Виртуализация добавляет слой между программой и железом, так что быстрее голого железа она не бывает. Её выгоды — изоляция, плотность и управляемость.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 1, 'Какое свойство монитора по Попеку и Голдбергу требует, чтобы подавляющее большинство команд гостя шло прямо на процессор?', '["Эквивалентность","Управление ресурсами","Изоляция","Эффективность"]', 3, 'Эквивалентность — гость ведёт себя как на настоящем компьютере, управление ресурсами — монитор контролирует всё выданное, эффективность — почти все команды исполняются без участия монитора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 2, 'О чём теорема Попека и Голдберга?', '["Монитор строится просто, если каждая чувствительная команда ещё и привилегирована","Каждая привилегированная команда обязана быть чувствительной","Гость обязан быть модифицирован под гипервизор","Без аппаратной поддержки монитор виртуальных машин построить нельзя"]', 0, 'Тогда любая опасная команда гостя вызывает ловушку, и процессор сам отдаёт управление монитору. Если есть чувствительные непривилегированные команды, схема даёт сбой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 3, 'Чем эмуляция отличается от виртуализации?', '["Эмуляция всегда быстрее, потому что не использует процессор хозяина","Эмуляция исполняет команды гостя программно, поэтому гость может быть другой архитектуры, но медленно; виртуализация гоняет их на настоящем процессоре","Эмуляция умеет изолировать гостей, а виртуализация — нет","Разницы нет, это два названия одной технологии"]', 1, 'QEMU в режиме трансляции эмулирует чужой процессор в разы и десятки раз медленнее. При виртуализации гость той же архитектуры, и его команды идут на железо напрямую.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 4, 'Как устроен KVM с точки зрения типов гипервизоров?', '["Это гипервизор типа 2: обычная программа поверх хозяйской ОС","Это контейнерная система без гипервизора","Гибрид: ядро Linux само становится гипервизором, а виртуальная машина — процессом QEMU","Это отдельная микро-ОС типа 1 без хозяйской системы"]', 2, 'KVM — модуль ядра: хозяйская система остаётся обычным Linux, но получает право запускать гостей напрямую на процессоре. Размывается граница между типом 1 и типом 2.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 2, 'theory', 'Квиз: trap-and-emulate, проблема x86 и обходные пути');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 0, 'Что происходит в схеме trap-and-emulate, когда ядро гостя выполняет привилегированную команду?', '["Команда выполняется на процессоре, а монитор узнаёт об этом позже из журнала","Процессор вызывает ловушку, монитор имитирует действие над виртуальным состоянием гостя и возвращает управление","Гость аварийно завершается и перезапускается","Монитор заранее транслирует весь код гостя"]', 1, 'Гость работает без привилегий, поэтому процессор сам останавливает опасную команду. Монитор меняет не настоящие регистры, а их виртуальные копии и отдаёт управление обратно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 1, 'Почему команда POPF мешает классической виртуализации x86?', '["Она слишком медленная, и монитор не успевает её обработать","Она привилегированная, и ловушек от неё слишком много","Вне нулевого кольца она молча игнорирует изменение флага прерываний и не вызывает ловушку, поэтому монитор её не видит","Она выполняется только внутри монитора"]', 2, 'POPF чувствительна, но не привилегирована: Робин и Ирвин нашли 17 таких команд. Гость уверен, что флаг сброшен, а на деле ничего не произошло, и ловушки нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 2, 'Как двоичная трансляция решает проблему чувствительных непривилегированных команд?', '["Сканирует код гостевого ядра, заменяет опасные команды безопасными вставками или вызовами монитора и кэширует результат","Запрещает гостевому ядру использовать флаги","Переводит гостя целиком в режим эмуляции","Подменяет ядро гостя ядром монитора"]', 0, 'Гость остаётся без правок, а монитор платит временем на первый проход и сложностью транслятора. Программы в кольце 3 транслировать не надо: опасных команд там нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 3, 'Что такое гипервызов в паравиртуализации?', '["Прерывание от устройства","Системный вызов из программы в ядро гостя","Ловушка, которую процессор вызывает по своей инициативе","Явное обращение ядра гостя к гипервизору, как системный вызов, но на уровень ниже"]', 3, 'Паравиртуальное ядро знает о гипервизоре и просит его сменить таблицу страниц или поставить таймер. Это быстро и точно, но требует доработанной ОС.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 2, 4, 'Какая величина сильнее всего определяет скорость программного обхода или паравиртуализации?', '["Тактовая частота хоста","Объём диска гостя","Число колец защиты","Число ловушек: каждая стоит порядка тысячи тактов и больше"]', 3, 'Обычная команда стоит доли такта, а переход в монитор и возврат — тысячи. Поэтому трансляция, пакетные гипервызовы и виртуальные флаги нацелены на сокращение ловушек.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 3, 'theory', 'Квиз: VT-x, AMD-V, VM exit, ARM EL2 и RISC-V H');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 0, 'Что такое режимы root и non-root в VT-x?', '["Режим монитора и режим гостя, в каждом из которых свои четыре кольца защиты","Привилегированные и обычные пользователи гостевой ОС","Два режима работы кэша процессора","Хостовая и гостевая файловые системы"]', 0, 'Ядро гостя работает в кольце 0 режима non-root и выполняет привилегированные команды как обычно, но монитор в режиме root решает, когда гость должен вернуть управление.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 1, 'Что хранится в VMCS?', '["Образ диска гостя","Таблицы страниц хозяина","Состояние гостя и хозяина, управляющие биты перехвата и причина последнего выхода","Список сетевых интерфейсов гостя"]', 2, 'VMCS — страница памяти, доступная только командами VMREAD и VMWRITE. У AMD ту же роль играет VMCB, а гостя запускает команда VMRUN.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 2, 'Какое из событий вызывает выход из гостя всегда, без настройки?', '["Сложение двух чисел","Запись в регистры общего назначения","Обращение к собственной памяти гостя","Выполнение команды CPUID"]', 3, 'CPUID, гипервызов VMCALL и команды самой виртуализации выходят всегда. Порты ввода-вывода, HLT, обращения к CR3 и MSR настраиваются битами VMCS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 3, 'На каком уровне исключений ARM работает гипервизор?', '["EL3","EL2","EL1","EL0"]', 1, 'Гостевое ядро работает на EL1, программы на EL0, а гипервизор на более привилегированном EL2. Из EL1 в EL2 попадают командой HVC. EL3 — защищённый монитор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 4, 'Зачем нужны метки адресных пространств (VPID у Intel, ASID у AMD)?', '["Они шифруют память гостя от хозяина","Они задают приоритет виртуальной машины","Они избавляют от полного сброса кэша трансляций при каждом переключении между гостем и монитором","Они нумеруют физические ядра процессора"]', 2, 'Записи кэша трансляций помечены владельцем, поэтому при входе и выходе не нужно выбрасывать их все: выход обходится дешевле.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 4, 'theory', 'Квиз: теневые таблицы, EPT/NPT и огромные страницы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 0, 'Зачем нужны теневые таблицы страниц в старой схеме виртуализации памяти?', '["Они хранят снимки памяти для миграции","Они сразу переводят виртуальный адрес гостя в хозяйский, и их подставляют в настоящий CR3","Они шифруют память гостя","Они ускоряют обмен с диском"]', 1, 'Гипервизор строит тень таблицы гостя и защищает исходную от записи: правка гостем вызывает выход, а тень обновляется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 1, 'Что происходит, когда гость меняет свою таблицу страниц при включённых EPT/NPT?', '["Гость делает выход, чтобы гипервизор обновил тень","Гость просит гипервизор сменить CR3","Гость меняет её без единого выхода: вложенные таблицы ведёт гипервизор","Гость блокирует остальные машины"]', 2, 'Первую таблицу ведёт гость, вторую — гипервизор, а обход обеих делает процессор. Правки гостя больше не перехватываются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 2, 'Сколько обращений к памяти нужно при промахе TLB с двумерным обходом, когда у гостя и у гипервизора по четыре уровня таблиц?', '["8","16","20","24"]', 3, 'Пять шагов гостя (четыре уровня и итоговый адрес) по пять обращений каждый без одного: 5 × 5 − 1 = 24. Без виртуализации — четыре.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 3, 'Чем огромные страницы помогают виртуализации?', '["Укорачивают обход таблиц и позволяют одной записи TLB покрыть больше памяти","Шифруют память гостя","Позволяют KSM сливать больше страниц","Избавляют от вложенных таблиц"]', 0, 'Страница 2 МиБ убирает один уровень обхода, 1 ГиБ — два. Заодно KSM с большими страницами не дружит: их приходится дробить.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 4, 'Что происходит при нарушении вложенных таблиц (EPT violation)?', '["Гость аварийно завершается","Процессор молча создаёт отображение","Таблицы гостя сбрасываются","Гость выходит в гипервизор, который выделяет страницу, достаёт её из подкачки, делает копию при записи или эмулирует устройство"]', 3, 'Это базовый механизм ленивого выделения, подкачки, копирования при записи и эмуляции устройств, на котором строятся следующие главы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 5, 'theory', 'Квиз: переподписка, баллонинг и KSM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 0, 'Почему переподписка памяти обычно работает?', '["Физическая память растёт сама","Гости редко используют всё выданное: часть занимают кэши и давно не читанные страницы","Гипервизор сжимает всю память","Гости обмениваются страницами между собой"]', 1, 'Пока не все гости требуют своё сразу, суммарное потребление остаётся ниже физической памяти. Риск — подкачка или аварийное убийство процессов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 1, 'Почему подкачку на уровне гипервизора считают последним средством?', '["Она запрещена в KVM","Она шифрует страницы","Гипервизор не знает, какие страницы гостю нужны; возможна и двойная подкачка","Она работает только для Windows"]', 2, 'Гипервизор может выгрузить рабочие данные, а гость при этом ещё и сам пользуется подкачкой, так что страница может оказаться на диске дважды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 2, 'Как работает баллонинг?', '["Драйвер в госте запрашивает страницы у гостевого ядра, которое само решает, чем пожертвовать, и сообщает адреса гипервизору","Гипервизор выгружает случайные страницы гостя","Баллон снижает частоту процессора","Баллон сжимает диск гостя"]', 0, 'Баллон — это обычная просьба внутри гостя: ядро гостя отдаёт сначала свободные страницы, затем кэш и лишь в крайнем случае вытесняет данные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 3, 'Что делает KSM?', '["Шифрует память гостей","Сжимает страницы","Переносит память на диск","Находит страницы с одинаковым содержимым и оставляет одну копию, отображая остальные на неё только для чтения"]', 3, 'При записи в слитую страницу вложенная таблица вызывает нарушение, и гипервизор делает копию для писавшего.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 4, 'Почему KSM отключают между недоверенными арендаторами?', '["Он слишком медленно сливает страницы","По времени записи в слитую страницу можно понять, что у соседа такое же содержимое","Он ломает вложенные таблицы","Он запрещён лицензией"]', 1, 'Запись в слитую страницу заметно медленнее обычной, и это даёт побочный канал для утечки содержимого соседей.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 6, 'theory', 'Квиз: эмуляция, virtio и vhost');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 0, 'Почему эмуляция настоящей сетевой карты медленна?', '["Драйверы для неё устарели","Каждое обращение драйвера к регистру устройства — выход в гипервизор, а на пакет их десяток","Эмуляция не поддерживает сеть","Эмулируемая карта работает на пониженной частоте"]', 1, 'Регистры устройства живут по адресам, которые перехватывает гипервизор, и каждое обращение — выход в QEMU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 1, 'Из чего состоит виртуальная очередь virtio?', '["Из одного кольца и одного регистра","Из трёх сокетов","Из таблицы дескрипторов, доступного кольца (гость → устройство) и использованного кольца (устройство → гость)","Из файла и канала"]', 2, 'Цепочка дескрипторов описывает буферы запроса, а в кольцах передаются только номера голов цепочек.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 2, 'Как virtio сокращает число выходов?', '["Запрещает прерывания в госте","Всегда опрашивает регистры","Использует по одному буферу","Гость кладёт в очередь много буферов и оповещает устройство один раз, а занятое устройство просит не звонить"]', 3, 'Пакетная обработка и флаги подавления оповещений уменьшают число выходов на порядки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 3, 'Что даёт vhost?', '["Переносит обработку очередей из процесса QEMU в поток ядра хоста, а оповещения идут через eventfd","Шифрует очереди","Заменяет virtio эмуляцией","Отключает прерывания гостя"]', 0, 'Запись гостя превращается в сигнал ioeventfd, а прерывание гостю — в сигнал irqfd, и QEMU уходит с горячего пути.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 4, 'Что такое vDPA?', '["Эмуляция старых сетевых карт","Способ сжатия образов дисков","Путь данных обслуживает железо, а гость видит стандартное устройство virtio","Проброс устройства без IOMMU"]', 2, 'Гость использует обычный драйвер virtio, поэтому такую машину проще мигрировать, чем с пробросом.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 7, 'theory', 'Квиз: IOMMU, VFIO и SR-IOV');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 0, 'Какая угроза делает IOMMU обязательной при пробросе устройства?', '["Устройство читает и пишет память напрямую (DMA) и может обратиться к чужой памяти","Устройство слишком быстрое","Гость забывает драйверы","Не хватает портов PCIe"]', 0, 'Устройство мимо процессора и вложенных таблиц использует адреса, которые дал драйвер гостя. IOMMU переводит и проверяет их.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 1, 'Что такое группа IOMMU?', '["Набор виртуальных машин","Устройства, которые IOMMU не может изолировать друг от друга, поэтому их отдают вместе","Группа процессоров","Набор образов дисков"]', 1, 'Если мост не изолирует устройства, IOMMU видит их как одно, и в VFIO отдавать приходится всю группу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 2, 'Какую цену платят за проброс устройства?', '["Теряется скорость","Нужен второй гипервизор","Пропадает сеть","Память закреплена, нет живой миграции и переподписки, машина привязана к серверу"]', 3, 'Закреплённые страницы нельзя вытеснять, надувать баллоном или сливать, а состояние железа трудно перенести.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 3, 'Что такое SR-IOV?', '["Способ шифрования трафика","Протокол миграции","Устройство показывает одну физическую функцию и много облегчённых виртуальных, которые отдают разным машинам","Формат образа диска"]', 2, 'Каждая виртуальная функция выглядит отдельным устройством PCIe с собственными очередями; коммутацию делает сама карта.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 4, 'Что даёт переотображение прерываний (interrupt remapping)?', '["Ускоряет дисковый ввод-вывод","По таблице проверяет, какое устройство в какой vCPU может слать прерывания, и отбрасывает чужие","Отключает прерывания гостя","Сжимает трафик устройства"]', 1, 'Так устройство в госте не сможет вызвать чужое прерывание; разрешённые доставляются в работающего гостя без выхода.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 8, 'theory', 'Квиз: KVM, QEMU и libvirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 0, 'Что делает модуль KVM?', '["Эмулирует устройства гостя","Превращает ядро Linux в гипервизор: гости работают прямо на процессоре","Управляет сетью хозяина","Шифрует образы дисков"]', 1, 'KVM даёт интерфейс /dev/kvm и вход в гостя; устройства и модель машины остаются за QEMU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 1, 'Как планируются виртуальные процессоры в KVM?', '["Собственным планировщиком гипервизора","Планировщиком гостя","Планировщиком Linux: каждый vCPU — обычный поток процесса QEMU","Только вручную администратором"]', 2, 'Поэтому на хозяине работают top, группы управления и привязка к ядрам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 2, 'Почему часть устройств, например контроллер прерываний и таймеры, эмулирует само ядро?', '["Чтобы не выходить в QEMU на каждое частое событие","Чтобы сэкономить диск","Из-за лицензий","Чтобы QEMU можно было не запускать"]', 0, 'Всё, что происходит часто и просто, переносится ближе к ядру; редкое и сложное остаётся в QEMU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 3, 'Почему QEMU считают главной поверхностью атаки на гипервизор?', '["Он не умеет шифровать","Он использует сеть","Он всегда работает от суперпользователя без ограничений","Он большой, написан на Си и эмулирует сотни устройств: ошибка в устройстве может стать побегом из гостя"]', 3, 'Поэтому его запускают от непривилегированного пользователя и ограничивают через seccomp, SELinux или AppArmor и cgroups.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 8, 4, 'Какую роль играет libvirt?', '["Эмулирует процессор","Слой управления: описывает машины в XML, запускает QEMU и управляет им","Заменяет ядро Linux","Хранит образы дисков"]', 1, 'Облачные платформы вроде OpenStack управляют серверами именно через libvirt.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 9, 'theory', 'Квиз: raw, qcow2, слои и снимки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 0, 'Чем raw отличается от qcow2?', '["raw — байты диска подряд без метаданных: быстро, но без снимков; qcow2 умеет снимки, слои и выделение по требованию","raw умеет снимки, а qcow2 — нет","Они одинаковы","raw всегда сжат"]', 0, 'raw кладут на логический том ради скорости, qcow2 выбирают ради гибкости.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 1, 'Как qcow2 находит кластер по гостевому адресу?', '["Линейным поиском по файлу","Через хеш-таблицу","Через две таблицы: L1 указывает на таблицы L2, а те хранят смещения кластеров в файле","По номеру сектора напрямую"]', 2, 'Пока гость в кластер не писал, самого кластера в файле нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 2, 'Что происходит при записи в слой поверх базового образа?', '["Изменяется базовый образ","Кластер копируется в верхний слой, база остаётся нетронутой","Запись отбрасывается","Слой удаляется"]', 1, 'Это копирование при записи: из одной базы можно запускать сотни машин, каждая хранит лишь свои изменения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 3, 'Что нужно для согласованного снимка диска работающей машины?', '["Выключить хозяина","Ничего: любой снимок согласован","Увеличить размер кластера","Через гостевой агент сбросить кэши и заморозить запись, сделать снимок и разморозить"]', 3, 'Иначе снимок будет согласован лишь «по сбою», как после внезапного отключения питания.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 4, 'Почему длинная цепочка слоёв замедляет чтение?', '["Чтение из глубокого слоя проходит через все вышестоящие, и каждый приходится проверять","Увеличивается размер кластера","Данные шифруются на каждом слое","Хозяин перегревается"]', 0, 'Поэтому слои периодически сливают (commit) или сплющивают цепочку в один образ.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 10, 'theory', 'Квиз: pre-copy, post-copy и грязные страницы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 0, 'Что такое грязные страницы при живой миграции?', '["Повреждённые страницы","Страницы, изменённые гостем после того, как их отправили","Страницы, заполненные нулями","Страницы гипервизора"]', 1, 'На каждом круге pre-copy отправляются только страницы, ставшие грязными за время предыдущего.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 1, 'Когда pre-copy сходится?', '["Когда скорость записи гостя в память меньше пропускной способности сети","Когда гость выключен","Когда память больше диска","Всегда"]', 0, 'Иначе остаток не уменьшается: помогают замедление гостя, сжатие или post-copy.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 2, 'Что делает post-copy?', '["Копирует всё до запуска на цели","Останавливает гостя на минуту","Сначала переключает гостя на цель, а страницы подтягивает по требованию через userfaultfd","Сжимает диск"]', 2, 'Каждая страница передаётся ровно один раз, поэтому миграция всегда завершается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 3, 'В чём главный риск post-copy?', '["Он проигрывает по скорости","Он не завершается","Он требует лицензии","Пока страницы разбросаны между серверами, сбой сети или любого сервера губит машину"]', 3, 'При pre-copy исходная копия цела до самого конца, поэтому там откат возможен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 4, 'Как журнал изменённых страниц (PML) ускоряет отслеживание грязных страниц?', '["Отключает запись в память","Железо само записывает адреса изменённых страниц в журнал, и выход нужен только при его заполнении","Сжимает память гостя","Копирует страницы в фоне"]', 1, 'Без PML каждая первая запись в страницу вызывает нарушение вложенных таблиц.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 11, 'theory', 'Квиз: vCPU, NUMA, pinning и steal time');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 0, 'Что показывает steal time гостю?', '["Время, когда vCPU был готов работать, но хозяин не дал физического ядра","Время простоя диска","Время сетевых задержек","Время загрузки гостя"]', 0, 'Стабильно высокое значение — признак перегруженного хоста или шумного соседа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 1, 'Чем квота (cpu.max) отличается от веса (cpu.weight)?', '["Вес ограничивает всегда, а квота — только при конкуренции","Они одинаковы","Квота ограничивает потребление всегда, вес делит ядро пропорционально лишь при конкуренции","Вес задаёт набор ядер"]', 2, 'Превышение квоты приводит к принудительным паузам — троттлингу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 2, 'Почему разным недоверенным машинам не отдают соседние потоки одного ядра (SMT)?', '["Это запрещено в BIOS","Они делят ресурсы и кэши ядра: возникает конкуренция и побочные каналы","Это ломает NUMA","Это увеличивает размер диска"]', 1, 'Закрепление vCPU обычно учитывает пары логических процессоров одного физического ядра.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 3, 'Почему NUMA важна для виртуальной машины?', '["NUMA ускоряет диски","NUMA нужна только для сети","NUMA включает гиперпоточность","Обращение к памяти чужого узла идёт через межсокетную шину и дороже, поэтому vCPU и память машины держат на одном узле"]', 3, 'Для больших машин гостю показывают виртуальную топологию NUMA.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 4, 'Чем платят за опрос перед остановкой vCPU (halt polling)?', '["Процессорным временем: опрос ускоряет пробуждение, но сжигает процессор","Памятью","Диском","Сетью"]', 0, 'Если прерывание приходит скоро, пробуждение мгновенное; если нет — опрос потрачен впустую.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 12, 'theory', 'Квиз: контейнеры и виртуальные машины');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 0, 'В чём главное различие контейнера и виртуальной машины?', '["У контейнера своё ядро","Контейнеры используют общее ядро хозяина, а машина приносит своё и отгорожена гипервизором","Виртуальные машины не умеют ограничивать ресурсы","Контейнерам нужен гипервизор"]', 1, 'Из общего ядра вытекают и скорость контейнеров, и острота вопроса безопасности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 1, 'Что делают пространства имён (namespaces)?', '["Показывают процессу собственную версию ресурсов: нумерацию, файлы, сеть, имя узла, пользователей","Ограничивают память","Шифруют диск","Планируют процессор"]', 0, 'Контейнер — набор таких пространств для группы процессов плюс ограничения cgroups.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 2, 'Что происходит при записи в файл нижнего слоя образа в overlayfs?', '["Меняется нижний слой","Запись отбрасывается","Файл копируется в верхний слой и меняется там","Слои сливаются"]', 2, 'Это копирование при записи; удаление ставит в верхнем слое метку whiteout, скрывающую файл.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 3, 'Почему контейнеров обычно недостаточно как единственной защиты для недоверенного кода?', '["Они слишком медленные","Они не поддерживают сеть","Им нужны права root","Граница проходит по системным вызовам общего ядра, и ошибка в любом из них даёт побег"]', 3, 'Для чужих арендаторов нужна граница сильнее: виртуальная машина, Kata или gVisor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 12, 4, 'Чем Kata Containers отличается от gVisor?', '["Они одинаковы","Kata запускает контейнер внутри лёгкой виртуальной машины (граница аппаратная), а gVisor подменяет ядро хозяина своим ядром в пользовательском пространстве","gVisor — это гипервизор","Kata всегда быстрее"]', 1, 'Kata платит памятью и стартом за аппаратную границу, gVisor — скоростью системных вызовов и совместимостью.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 13, 'theory', 'Квиз: Xen, ESXi, облака и microVM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 0, 'Что такое Dom0 в Xen?', '["Гостевая машина без прав","Привилегированная машина, которая управляет системой и держит драйверы","Другое название гипервизора","Сетевой интерфейс"]', 1, 'Остальные гости называются DomU; такое разделение уменьшает доверенную часть.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 1, 'Что вынесено на специальные карты в AWS Nitro?', '["Сеть, диски и функции безопасности — на карты со своими процессорами","Только планировщик","Образы гостей","Весь гипервизор"]', 0, 'Хозяину остаётся минимум: запускать гостей на KVM.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 2, 'Что убирают из microVM ради скорости и безопасности?', '["Сеть","Ядро гостя","Прошивку, шину PCI, видео и USB","Память"]', 2, 'Остаётся горсть устройств virtio, сокет, последовательный порт и сброс.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 3, 'Почему микро-виртуальная машина стартует так быстро?', '["Использует более быстрый процессор","Не использует память","Запускается на видеокарте","Загружает ядро напрямую, без прошивки и загрузчика, а из снимка память отображается лениво"]', 3, 'Так функции в бессерверных сервисах запускаются за миллисекунды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 4, 'Зачем нужен jailer у Firecracker?', '["Для миграции","Запирает процесс монитора: cgroups, пространства имён, chroot, сброс привилегий, seccomp","Для загрузки ядра","Для сети"]', 1, 'Побег должен преодолеть несколько уровней защиты подряд.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 14, 'theory', 'Квиз: безопасность виртуализации');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 0, 'Где чаще всего находили побеги из гостя?', '["В планировщике","В файловой системе гостя","В коде эмуляции устройств","В DNS"]', 2, 'Пример — ошибка в эмуляции забытого контроллера дискет в 2015 году.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 1, 'Как работает атака Prime+Probe?', '["Атакующий читает память жертвы напрямую","Атакующий подменяет прошивку","Атакующий перезагружает хост","Атакующий заполняет кэш, жертва вытесняет часть записей, а по времени доступа видно, какие наборы она использовала"]', 3, 'Поэтому ядра и кэши не делят между недоверенными, а секретный код пишут без зависимости от данных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 2, 'Чем Foreshadow (L1TF) особенно опасен для виртуализации?', '["Гость выключал хозяина","Гость мог читать данные из кэша первого уровня хозяина","Он ломал IOMMU","Он менял BIOS"]', 1, 'Ответ — микрокод, сброс L1D при входе в гостя и отключение SMT между недоверенными.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 3, 'Что дают конфиденциальные вычисления (SEV-SNP, TDX)?', '["Шифрование только сети","Защиту диска хозяина","Защиту исходного кода гипервизора","Память ВМ шифруется ключом, недоступным гипервизору, и защищена от подмены"]', 3, 'Гипервизор по-прежнему планирует машину, но читать её память больше не может.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 4, 'Зачем нужна удалённая аттестация?', '["Клиент проверяет подписанное процессором измерение образа и только потом выдаёт машине секреты","Она ускоряет миграцию","Она сжимает образ","Она включает KSM"]', 0, 'Так клиент убеждается, что машина действительно запущена в защищённом режиме.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 15, 'theory', 'Квиз: вложенная виртуализация');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 0, 'Почему вложенная виртуализация сложна, если у процессора один режим монитора?', '["Режим монитора один, поэтому гипервизор L0 эмулирует расширения виртуализации для L1","Процессор не поддерживает несколько ядер","Гости не умеют загружаться","Для этого нужны два процессора"]', 0, 'Для гостя L1 иллюзию настоящих расширений целиком поддерживает самый нижний гипервизор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 1, 'Что такое VMCS 0-2?', '["Описание, которое L1 считает настоящим","Настоящая структура, с которой L0 запускает L2, собранная из описаний L0 и L1","Таблица страниц L2","Журнал выходов"]', 1, 'Именно её L0 склеивает при каждом входе в L2; VMCS 1-2 — это лишь описание, которое видит L1.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 2, 'Что даёт VMCS shadowing?', '["Шифрует управляющую структуру","Отключает выходы L2","L1 читает и пишет разрешённые поля VMCS без выхода в L0, поэтому цепочка выходов короче","Ускоряет диск"]', 2, 'Без неё каждое обращение L1 к полю структуры — выход в L0, и один выход L2 порождает десятки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 3, 'Как решается проблема таблиц страниц при вложенности?', '["L2 использует таблицы хоста напрямую","Таблицы больше не нужны","Используются только теневые таблицы L1","L0 склеивает EPT L1 для L2 и свою EPT для L1 в одну таблицу"]', 3, 'Железо знает один уровень вложенных таблиц, поэтому L0 строит композицию двух.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 4, 'Как внутри гостя проверить, что запуск второго гипервизора возможен?', '["Запустить fsck","Посмотреть признаки vmx или svm в /proc/cpuinfo и параметр nested модуля KVM","Проверить размер диска","Посмотреть версию BIOS"]', 1, 'Если у L1 нет признаков виртуализации, второй гипервизор запустится только на программной трансляции.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 16, 'theory', 'Квиз: практика с QEMU/KVM и наблюдаемость');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 0, 'Что проверить первым делом перед запуском QEMU с KVM?', '["Размер оперативной памяти","Признаки vmx или svm и доступность /dev/kvm","Версию командной оболочки","Скорость сети"]', 1, 'virt-host-validate проверяет сразу процессор, модули ядра, группы управления и IOMMU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 1, 'Что показывает perf kvm stat?', '["Список файлов гостя","Размер образа","Причины выходов из гостя и долю времени на каждую","Температуру процессора"]', 2, 'Обычно лидируют остановка процессора, внешние прерывания, записи в MSR и нарушения EPT.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 2, 'Много IO_INSTRUCTION в отчёте — на что это указывает?', '["Сеть слишком быстрая","Гость выключен","Диск зашифрован","Где-то идёт эмуляция устройства через порты вместо паравиртуальных"]', 3, 'Заменить эмуляцию на virtio — самый частый способ сократить выходы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 3, 'Что делает qemu-img commit?', '["Создаёт снимок состояния машины","Сливает слой в базовый образ","Шифрует образ","Копирует образ по сети"]', 1, 'Сплющить всю цепочку в один файл можно командой convert.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 4, 'Что в первую очередь проверить при медленной сети гостя?', '["Устройство паравиртуальное ли, включён ли vhost и хватает ли очередей","Цвет терминала","Размер swap","Только версию ядра гостя"]', 0, 'Эмуляция карты и однопоточная обработка очередей — самые частые причины.');
